import {SECTIONS, Sidebar} from './Sidebar';
import type {SectionId} from './Sidebar';
import './app.css';

export function App() {
  const [section, setSection] = React.useState<SectionId>('orders');
  const [collapsed, setCollapsed] = React.useState(false);

  return (
    <div className="layout">
      <Sidebar
